PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS leitores (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,email TEXT NOT NULL UNIQUE,telefone TEXT,senha_hash TEXT NOT NULL,tipo TEXT NOT NULL CHECK(tipo IN ('aluno','professor','gestao')),status TEXT NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo','pendente')),criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alunos (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL UNIQUE,ra TEXT NOT NULL UNIQUE,ra_digito TEXT,etapa TEXT,serie TEXT,turma TEXT,numero_chamada INTEGER,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS professores (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL UNIQUE,matricula TEXT UNIQUE,disciplina TEXT,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS gestao (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL UNIQUE,cargo TEXT,nivel_acesso TEXT NOT NULL DEFAULT 'gestao',FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categorias (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE,descricao TEXT);
CREATE TABLE IF NOT EXISTS livros (id INTEGER PRIMARY KEY AUTOINCREMENT,categoria_id INTEGER,titulo TEXT NOT NULL,autor TEXT NOT NULL,editora TEXT,isbn TEXT UNIQUE,ano_publicacao INTEGER,descricao TEXT,capa TEXT,ativo INTEGER NOT NULL DEFAULT 1,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(categoria_id) REFERENCES categorias(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS localizacoes (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE,descricao TEXT);
CREATE TABLE IF NOT EXISTS exemplares (id INTEGER PRIMARY KEY AUTOINCREMENT,livro_id INTEGER NOT NULL,localizacao_id INTEGER,codigo TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'disponivel' CHECK(status IN ('disponivel','emprestado','reservado','danificado','perdido')),observacao TEXT,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE,FOREIGN KEY(localizacao_id) REFERENCES localizacoes(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS emprestimos (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,exemplar_id INTEGER NOT NULL,data_emprestimo DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,data_prevista_devolucao DATETIME NOT NULL,data_devolucao DATETIME,codigo_seguranca TEXT UNIQUE,codigo_devolucao TEXT UNIQUE,codigo_devolucao_criado_em DATETIME,renovacoes INTEGER NOT NULL DEFAULT 0,retirada_confirmada INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','devolvido','atrasado')),FOREIGN KEY(usuario_id) REFERENCES leitores(id),FOREIGN KEY(exemplar_id) REFERENCES exemplares(id));
CREATE TABLE IF NOT EXISTS reservas (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,livro_id INTEGER NOT NULL,data_reserva DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,prazo_retirada DATETIME,status TEXT NOT NULL DEFAULT 'fila' CHECK(status IN ('fila','pronto','retirada','cancelada')),FOREIGN KEY(usuario_id) REFERENCES leitores(id),FOREIGN KEY(livro_id) REFERENCES livros(id));
CREATE TABLE IF NOT EXISTS solicitacoes_emprestimo (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,livro_id INTEGER NOT NULL,data_solicitacao DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,data_desejada DATE,status TEXT NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovada','recusada','cancelada')),motivo TEXT,analisado_em DATETIME,analisado_por INTEGER,emprestimo_id INTEGER,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE,FOREIGN KEY(analisado_por) REFERENCES leitores(id) ON DELETE SET NULL,FOREIGN KEY(emprestimo_id) REFERENCES emprestimos(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_solicitacoes_usuario ON solicitacoes_emprestimo(usuario_id); CREATE INDEX IF NOT EXISTS idx_solicitacoes_status ON solicitacoes_emprestimo(status);
CREATE TABLE IF NOT EXISTS favoritos (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,livro_id INTEGER NOT NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(usuario_id,livro_id),FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE,FOREIGN KEY(livro_id) REFERENCES livros(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notificacoes (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,titulo TEXT NOT NULL,mensagem TEXT NOT NULL,tipo TEXT NOT NULL DEFAULT 'info',lida INTEGER NOT NULL DEFAULT 0,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS configuracoes (id INTEGER PRIMARY KEY CHECK(id=1),dias_emprestimo INTEGER NOT NULL DEFAULT 14,limite_livros_aluno INTEGER NOT NULL DEFAULT 5,limite_livros_professor INTEGER NOT NULL DEFAULT 5,maximo_renovacoes INTEGER NOT NULL DEFAULT 2,permitir_reservas INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS idx_livros_titulo ON livros(titulo); CREATE INDEX IF NOT EXISTS idx_emprestimos_usuario ON emprestimos(usuario_id); CREATE INDEX IF NOT EXISTS idx_reservas_livro ON reservas(livro_id); CREATE INDEX IF NOT EXISTS idx_emprestimos_usuario_status ON emprestimos(usuario_id,status); CREATE INDEX IF NOT EXISTS idx_emprestimos_status_prazo ON emprestimos(status,data_prevista_devolucao); CREATE INDEX IF NOT EXISTS idx_exemplares_livro_status ON exemplares(livro_id,status); CREATE INDEX IF NOT EXISTS idx_reservas_usuario_status ON reservas(usuario_id,status); CREATE INDEX IF NOT EXISTS idx_reservas_status_prazo ON reservas(status,prazo_retirada); CREATE INDEX IF NOT EXISTS idx_notificacoes_usuario_lida_criado ON notificacoes(usuario_id,lida,criado_em); CREATE INDEX IF NOT EXISTS idx_leitores_tipo_status ON leitores(tipo,status);

CREATE TABLE IF NOT EXISTS turmas (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,ano INTEGER,etapa TEXT,status TEXT NOT NULL DEFAULT 'ativo' CHECK(status IN ('ativo','inativo','pendente')),criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(nome,ano));
CREATE TABLE IF NOT EXISTS recuperacao_senha (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,codigo_hash TEXT NOT NULL,expira_em DATETIME NOT NULL,usado INTEGER NOT NULL DEFAULT 0,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_recuperacao_senha_usuario ON recuperacao_senha(usuario_id); CREATE INDEX IF NOT EXISTS idx_recuperacao_senha_expiracao ON recuperacao_senha(usuario_id,expira_em,usado);

CREATE TABLE IF NOT EXISTS contatos (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL,email TEXT NOT NULL,mensagem TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'novo' CHECK(status IN ('novo','lido','respondido')),criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_contatos_status_criado ON contatos(status,criado_em);

CREATE TABLE IF NOT EXISTS multas (id INTEGER PRIMARY KEY AUTOINCREMENT,emprestimo_id INTEGER NOT NULL UNIQUE,usuario_id INTEGER NOT NULL,valor_dia REAL NOT NULL DEFAULT 5,status TEXT NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','paga','cancelada')),criada_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,paga_em DATETIME,FOREIGN KEY(emprestimo_id) REFERENCES emprestimos(id) ON DELETE CASCADE,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_multas_status_usuario ON multas(status,usuario_id);

CREATE INDEX IF NOT EXISTS idx_turmas_status_nome ON turmas(status,nome);

CREATE TABLE IF NOT EXISTS penalidades (id INTEGER PRIMARY KEY AUTOINCREMENT,usuario_id INTEGER NOT NULL,emprestimo_id INTEGER,descricao TEXT NOT NULL,tipo TEXT NOT NULL DEFAULT 'advertencia' CHECK(tipo IN ('advertencia','bloqueio_3','bloqueio_7','bloqueio_15','bloqueio_regularizacao')),dias_bloqueio INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'ativa' CHECK(status IN ('ativa','cumprida','cancelada')),criada_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,inicio_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,fim_em DATETIME,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE,FOREIGN KEY(emprestimo_id) REFERENCES emprestimos(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_penalidades_usuario_status ON penalidades(usuario_id,status);

CREATE TABLE IF NOT EXISTS preferencias_notificacao (usuario_id INTEGER PRIMARY KEY,livros INTEGER NOT NULL DEFAULT 1,emprestimos INTEGER NOT NULL DEFAULT 1,reservas INTEGER NOT NULL DEFAULT 1,atrasos INTEGER NOT NULL DEFAULT 1,devolucoes INTEGER NOT NULL DEFAULT 1,cadastros INTEGER NOT NULL DEFAULT 1,informativos INTEGER NOT NULL DEFAULT 1,atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES leitores(id) ON DELETE CASCADE);
